VAR
    Startup_Timer : TON;
END_VAR

// If the motor is commanded to start and running, but speed is low, trigger timer
Startup_Timer(IN := Start_Command AND Motor_Running AND (Motor_Speed < 50.0),
              PT := T#5S);

// If timer times out, shut down the motor
IF Startup_Timer.Q THEN
    Motor_Stop := TRUE;
END_IF;

// Reset the stop command when the start command is removed or fault is reset
IF NOT Start_Command AND Fault_Reset THEN
    Motor_Stop := FALSE;
END_IF;

